import de from './locales/de.json';
import es from './locales/es.json';
import it from './locales/it.json';
import tr from './locales/tr.json';

export const SUPPORTED_LANGUAGES = [
  { code: 'fr', label: 'Français', flag: '', countryCode: 'fr', dir: 'ltr' },
  { code: 'en', label: 'English',  flag: '', countryCode: 'gb', dir: 'ltr' },
  { code: 'ar', label: 'العربية',  flag: '', countryCode: 'tn', dir: 'rtl' },
  { code: 'de', label: 'Deutsch',  flag: '', countryCode: 'de', dir: 'ltr' },
  { code: 'es', label: 'Español',  flag: '', countryCode: 'es', dir: 'ltr' },
  { code: 'it', label: 'Italiano', flag: '', countryCode: 'it', dir: 'ltr' },
  { code: 'tr', label: 'Türkçe',   flag: '', countryCode: 'tr', dir: 'ltr' },
];

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      fr: { translation: fr },
      en: { translation: en },
      ar: { translation: ar },
      de: { translation: de },
      es: { translation: es },
      it: { translation: it },
      tr: { translation: tr },
    },
    fallbackLng: 'fr',
    supportedLngs: ['fr', 'en', 'ar', 'de', 'es', 'it', 'tr'],
    detection: {
      order: ['localStorage', 'navigator', 'htmlTag'],
      caches: ['localStorage'],
      lookupLocalStorage: 'aidaa_language',
    },
    interpolation: {
      escapeValue: false,
    },
  });

// Apply RTL direction when Arabic is selected
i18n.on('languageChanged', (lng) => {
  const lang = SUPPORTED_LANGUAGES.find((l) => l.code === lng);
  if (lang) {
    document.documentElement.dir = lang.dir;
    document.documentElement.lang = lng;
  }
});

export default i18n;

// ============================================================================
// ADMIN PANEL — Design matching adminIndex.html (orange theme + FontAwesome)
// ============================================================================

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../features/auth/hooks/useAuth';
import api from '../lib/api';
import { ContentItem, ContentFormData, User } from '../features/content/types/content.types';
import { ContentCard } from '../features/admin/components/ContentCard';
import { EditContentModal } from '../features/admin/components/EditContentModal';
import { DeleteContentModal } from '../features/admin/components/DeleteContentModal';
import { StatCard, Section, useToast, ToastStack } from '../components';
import LanguageSwitcher from '../components/ui/LanguageSwitcher';

// ── Types ──────────────────────────────────────────────────────────────────
type ViewType = 'content' | 'upload' | 'users' | 'registrations' | 'relations' | 'messages' | 'notes';
type UserRole = 'admin' | 'parent' | 'professional';
interface UserFormState { name: string; email: string; password: string; role: UserRole; }
interface ApiResult<T> { success: boolean; data: T; message?: string; }

interface RelationRow {
  id: number; status: string; invited_at: string;
  parent_name: string; parent_email: string;
  professional_name: string; professional_email: string;
}
interface MessageRow {
  id: number; content: string; created_at: string; is_read: number;
  sender_name: string; sender_role: string;
  receiver_name: string; receiver_role: string;
  child_name: string;
}
interface NoteRow {
  id: number; content: string; date: string;
  professional_name: string; professional_email: string;
  child_name: string;
}


// ── Nav config ─────────────────────────────────────────────────────────────
const NAV_IDS = [
  { id: 'content',       fa: 'fa-solid fa-swatchbook',          key: 'navLibrary'       },
  { id: 'upload',        fa: 'fa-solid fa-cloud-arrow-up',       key: 'navUpload'        },
  { id: 'users',         fa: 'fa-solid fa-users',                key: 'navUsers'         },
  { id: 'registrations', fa: 'fa-solid fa-bell',                 key: 'navRegistrations' },
  { id: 'relations',     fa: 'fa-solid fa-link',                 key: 'navRelations'     },
  { id: 'messages',      fa: 'fa-solid fa-comments',             key: 'navMessages'      },
  { id: 'notes',         fa: 'fa-solid fa-notes-medical',        key: 'navNotes'         },
] as const;

const ROLE_FA: Record<string, string> = {
  admin:        'fa-solid fa-shield-halved',
  parent:       'fa-solid fa-house-user',
  professional: 'fa-solid fa-stethoscope',
};
const ROLE_COLOR: Record<string, string> = {
  admin:        'bg-purple-100 text-purple-700',
  parent:       'bg-orange-100 text-orange-700',
  professional: 'bg-blue-100 text-blue-700',
};

// ── Section wrapper (uses shared Section from components) ───────────────

// ── Input / Select helpers ─────────────────────────────────────────────────
const inputCls = 'w-full px-4 py-3.5 border border-slate-200 rounded-xl text-slate-900 placeholder-slate-400 bg-white text-[15px] focus:outline-none focus:ring-4 focus:ring-brand-orange/10 focus:border-brand-orange transition-all';
const labelCls = 'block text-sm font-semibold text-slate-800 mb-2';

// ── Main Component ─────────────────────────────────────────────────────────
export const AdminPanel = (): JSX.Element => {
  const { logout, user } = useAuth();
  const { toasts, add: toast, remove: removeToast } = useToast();
  const { t } = useTranslation();

  const [view,     setView]     = useState<ViewType>('content');
  const [content,  setContent]  = useState<ContentItem[]>([]);
  const [users,    setUsers]    = useState<User[]>([]);
  const [pending,  setPending]  = useState<User[]>([]);
  const [notifCount, setNotifCount] = useState(0);
  const [loading,  setLoading]  = useState(false);
  const [actLoading, setActLoading] = useState(false);

  // ── Admin monitoring state ─────────────────────────────────────────────
  const [relations,     setRelations]     = useState<RelationRow[]>([]);
  const [adminMessages, setAdminMessages] = useState<MessageRow[]>([]);
  const [adminNotes,    setAdminNotes]    = useState<NoteRow[]>([]);
  const [monitorLoading, setMonitorLoading] = useState(false);

  const [createForm, setCreateForm] = useState<UserFormState>({ name: '', email: '', password: '', role: 'parent' });
  const [editId,     setEditId]     = useState<number | null>(null);
  const [editForm,   setEditForm]   = useState<Omit<UserFormState, 'password'> | null>(null);

  const [editingContent,    setEditingContent]    = useState<ContentItem | null>(null);
  const [deletingContentId, setDeletingContentId] = useState<number | null>(null);
  const [deletingTitle,     setDeletingTitle]     = useState('');

  const [uploadForm, setUploadForm] = useState<ContentFormData>({
    title: '', type: 'video', description: '', category: '',
    categoryColor: '#f97316', emoji: '', duration: '',
    steps: 5, minutes: 15, emojiColor: '#d1fae5',
    ageGroup: '4-6', level: '1', language: 'fr', file: null,
  });

  // ── Filters state ──────────────────────────────────────────────────────────
  const [libTypeFilter, setLibTypeFilter]   = useState<'all' | 'video' | 'audio' | 'activity'>('all');
  const [libLangFilter, setLibLangFilter]   = useState<'all' | 'fr' | 'ar' | 'tn'>('all');
  const [msgDateFilter, setMsgDateFilter]   = useState('');
  const [msgNameFilter, setMsgNameFilter]   = useState('');
  const [msgRoleFilter, setMsgRoleFilter]   = useState<'all' | 'parent' | 'professional'>('all');

  // ── Data fetchers ──────────────────────────────────────────────────────
  const fetchContent = async () => { const { data } = await api.get<ApiResult<ContentItem[]>>('/api/content'); if (data.success) setContent(data.data); };
  const fetchUsers   = async () => { const { data } = await api.get<ApiResult<User[]>>('/api/users'); if (data.success) setUsers(data.data); };
  const fetchPending = async () => { try { const { data } = await api.get<ApiResult<User[]>>('/api/admin/pending-registrations'); if (data.success) { setPending(data.data); setNotifCount(data.data.length); } } catch { /* silent */ } };

  const fetchRelations = async () => { try { setMonitorLoading(true); const { data } = await api.get<ApiResult<RelationRow[]>>('/api/admin/relations'); if (data.success) setRelations(data.data); } catch { /* silent */ } finally { setMonitorLoading(false); } };
  const fetchAdminMessages = async () => { try { setMonitorLoading(true); const { data } = await api.get<ApiResult<MessageRow[]>>('/api/admin/messages'); if (data.success) setAdminMessages(data.data); } catch { /* silent */ } finally { setMonitorLoading(false); } };
  const fetchAdminNotes    = async () => { try { setMonitorLoading(true); const { data } = await api.get<ApiResult<NoteRow[]>>('/api/admin/notes'); if (data.success) setAdminNotes(data.data); } catch { /* silent */ } finally { setMonitorLoading(false); } };

  const handleDeleteRelation = async (id: number) => {
    if (!window.confirm('Supprimer définitivement cette relation ? Le professionnel n\'aura plus accès aux données de ce parent.')) return;
    try {
      const { data } = await api.delete<ApiResult<null>>(`/api/admin/relations/${id}`);
      if (data.success) { toast('Relation supprimée ✓'); await fetchRelations(); }
      else toast(data.message || 'Erreur', 'error');
    } catch { toast('Erreur réseau.', 'error'); }
  };

  useEffect(() => { setLoading(true); Promise.all([fetchContent(), fetchUsers()]).finally(() => setLoading(false)); }, []);
  useEffect(() => { fetchPending(); const t = setInterval(fetchPending, 30000); return () => clearInterval(t); }, []);
  useEffect(() => {
    if (view === 'relations') fetchRelations();
    else if (view === 'messages') fetchAdminMessages();
    else if (view === 'notes') fetchAdminNotes();
  }, [view]);

  // ── Handlers ──────────────────────────────────────────────────────────
  const handleApprove = async (id: number) => { try { setActLoading(true); await api.post(`/api/admin/approve-registration/${id}`); await Promise.all([fetchPending(), fetchUsers()]); toast('Inscription acceptée ✓'); } catch { toast("Erreur lors de l'acceptation", 'error'); } finally { setActLoading(false); } };
  const handleReject  = async (id: number) => { try { setActLoading(true); await api.post(`/api/admin/reject-registration/${id}`); await fetchPending(); toast('Demande refusée'); } catch { toast('Erreur lors du refus', 'error'); } finally { setActLoading(false); } };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!createForm.name.trim() || !createForm.email.trim() || !createForm.password.trim()) { toast('Tous les champs sont requis', 'error'); return; }
    try {
      setActLoading(true);
      const { data } = await api.post<ApiResult<User>>('/api/users', { name: createForm.name.trim(), email: createForm.email.trim().toLowerCase(), password: createForm.password, role: createForm.role });
      if (!data.success) { toast(data.message || 'Erreur création', 'error'); return; }
      setCreateForm({ name: '', email: '', password: '', role: 'parent' });
      await fetchUsers(); toast('Utilisateur créé ✓');
    } catch { toast('Erreur lors de la création', 'error'); } finally { setActLoading(false); }
  };

  const handleEditSaveUser = async (u: User) => {
    if (!editForm) return;
    try {
      setActLoading(true);
      const { data } = await api.put<ApiResult<User>>(`/api/users/${u.id}`, { name: editForm.name.trim(), email: editForm.email.trim().toLowerCase(), role: editForm.role, is_active: u.is_active });
      if (!data.success) { toast(data.message || 'Erreur mise à jour', 'error'); return; }
      setEditId(null); setEditForm(null); await fetchUsers(); toast('Utilisateur mis à jour ✓');
    } catch { toast('Erreur mise à jour', 'error'); } finally { setActLoading(false); }
  };

  const handleDeleteUser = async (u: User) => {
    if (!window.confirm(`Supprimer définitivement ${u.name} ?`)) return;
    try { setActLoading(true); const { data } = await api.delete<ApiResult<null>>(`/api/users/${u.id}`); if (!data.success) { toast(data.message || 'Erreur', 'error'); return; } await fetchUsers(); toast(`${u.name} supprimé`); } catch { toast('Erreur suppression', 'error'); } finally { setActLoading(false); }
  };

  const handleUploadChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    setUploadForm(p => ({ ...p, [name]: type === 'number' ? (value ? parseInt(value) : undefined) : value }));
  };

  const handleUploadSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!uploadForm.file || !uploadForm.title) { toast('Fichier et titre requis', 'error'); return; }
    try {
      setLoading(true);
      const fd = new FormData();
      fd.append('file', uploadForm.file); fd.append('title', uploadForm.title); fd.append('type', uploadForm.type);
      fd.append('description', uploadForm.description || ''); fd.append('category', uploadForm.category || '');
      fd.append('category_color', uploadForm.categoryColor || '#f97316'); fd.append('emoji', uploadForm.emoji || '');
      fd.append('age_group', uploadForm.ageGroup || '4-6'); fd.append('level', uploadForm.level?.toString() || '1');
      fd.append('language', uploadForm.language || 'fr');
      if (uploadForm.type === 'video' && uploadForm.duration) fd.append('duration', uploadForm.duration);
      if (uploadForm.type === 'activity') { fd.append('steps', (uploadForm.steps || 5).toString()); fd.append('minutes', (uploadForm.minutes || 15).toString()); fd.append('emoji_color', uploadForm.emojiColor || '#d1fae5'); }
      const { data } = await api.post<ApiResult<ContentItem>>('/api/content/upload', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      if (data.success) { toast('Contenu uploadé ✓'); setUploadForm({ title: '', type: 'video', description: '', category: '', categoryColor: '#f97316', emoji: '', duration: '', steps: 5, minutes: 15, emojiColor: '#d1fae5', ageGroup: '4-6', level: '1', language: 'fr', file: null }); await fetchContent(); }
      else toast(data.message || 'Erreur upload', 'error');
    } catch (err) { toast(err instanceof Error ? err.message : 'Erreur upload', 'error'); } finally { setLoading(false); }
  };

  const handleEditSave = async (contentId: number, formData: ContentFormData) => {
    try { setLoading(true); const { data } = await api.put<ApiResult<ContentItem>>(`/api/content/${contentId}`, { title: formData.title, type: formData.type, category: formData.category, category_color: formData.categoryColor, emoji: formData.emoji, duration: formData.duration, steps: formData.steps, minutes: formData.minutes, emoji_color: formData.emojiColor, description: formData.description, age_group: formData.ageGroup, level: formData.level }); if (data.success) { toast('Contenu mis à jour ✓'); setEditingContent(null); await fetchContent(); } else toast('Erreur: ' + data.message, 'error'); } catch { toast('Erreur mise à jour', 'error'); } finally { setLoading(false); }
  };

  const handleDeleteConfirm = async () => {
    if (!deletingContentId) return;
    try { setLoading(true); const { data } = await api.delete<ApiResult<null>>(`/api/content/${deletingContentId}`); if (data.success) { toast('Contenu supprimé'); setDeletingContentId(null); setDeletingTitle(''); await fetchContent(); } else toast('Erreur: ' + data.message, 'error'); } catch { toast('Erreur suppression', 'error'); } finally { setLoading(false); }
  };

  const activeUsers    = users.filter(u => !!u.is_active).length;
  const adminInitial   = user?.name?.charAt(0).toUpperCase() || 'A';
  const currentNavItem = NAV_IDS.find(n => n.id === view);

  // ── Render ─────────────────────────────────────────────────────────────
  return (
    <div className="font-sans antialiased flex h-screen overflow-hidden bg-slate-50 animate-page-in">

      {/* ══════════════ SIDEBAR ══════════════ */}
      <aside
        className="w-[280px] relative flex flex-col z-10 shrink-0"
        style={{
          background: '#F97316',
          backgroundImage: 'linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px)',
          backgroundSize: '20px 20px',
          boxShadow: '4px 0 15px rgba(249,115,22,0.2)',
        }}
      >
        {/* Brand */}
        <div className="flex items-center gap-4 px-6 py-4">
          <div className="w-12 h-12 bg-white text-brand-orange rounded-xl flex items-center justify-center text-2xl shadow-sm shrink-0">
            <i className="fa-solid fa-puzzle-piece" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-white tracking-tight leading-none">AIDAA</h2>
            <span className="text-[11px] text-white/80 font-medium uppercase tracking-widest">{t('adminDash.title')}</span>
          </div>
        </div>

        {/* Admin profile card — top */}
        <div className="px-5 pb-2 shrink-0">
          <div className="flex items-center gap-3 bg-white/10 border border-white/20 rounded-xl p-3">
            <div className="w-9 h-9 rounded-full bg-white flex items-center justify-center font-bold text-brand-orange text-sm shrink-0">
              {adminInitial}
            </div>
            <div className="min-w-0">
              <p className="text-sm font-semibold text-white truncate">{user?.name || 'Admin'}</p>
              <p className="text-xs text-white/80">{t('adminDash.administrator')}</p>
            </div>
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 px-5 flex flex-col gap-2">
          {NAV_IDS.map(n => (
            <button key={n.id}
              className={`flex items-center w-full px-5 py-3.5 rounded-xl font-semibold text-[15px] border transition-all
                ${view === n.id
                  ? 'bg-white text-brand-orange shadow-md border-transparent'
                  : 'text-white border-transparent hover:bg-white/15 hover:border-white/20'}`}
              onClick={() => setView(n.id as ViewType)}
            >
              <i className={`${n.fa} w-6 mr-3 text-lg ${view === n.id ? 'text-brand-orange opacity-100' : 'opacity-80'}`} />
              {t(`adminDash.${n.key}`)}
              {n.id === 'registrations' && notifCount > 0 && (
                <span className="ml-auto w-5 h-5 rounded-full bg-white text-brand-orange text-[11px] font-bold flex items-center justify-center">
                  {notifCount}
                </span>
              )}
            </button>
          ))}
        </nav>

        {/* Footer — logout only */}
        <div className="px-5 pb-5 flex flex-col gap-2">
          <div className="flex justify-center">
            <LanguageSwitcher dropDirection="up" />
          </div>
          <button onClick={logout}
            className="w-full flex items-center justify-center gap-2 bg-black/15 hover:bg-black/25 text-white font-semibold py-3 rounded-lg transition-all text-sm">
            {t('adminDash.disconnect')} <i className="fa-solid fa-arrow-right-from-bracket" />
          </button>
        </div>
      </aside>

      {/* ══════════════ MAIN ══════════════════ */}
      <div className="flex-1 flex flex-col overflow-hidden">

        {/* Top header */}
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-10 shrink-0">
          <div className="flex items-baseline gap-2">
            <span className="text-sm text-slate-500 font-medium">{t('adminDash.breadcrumb')}</span>
            <span className="text-xl font-bold text-slate-900">{currentNavItem ? t(`adminDash.${currentNavItem.key}`) : ''}</span>
          </div>
          <button
            className="relative w-11 h-11 rounded-full border border-slate-200 bg-white text-slate-600 flex items-center justify-center hover:bg-slate-50 transition text-lg"
            onClick={() => setView('registrations')}
            title="Demandes en attente"
          >
            <i className="fa-regular fa-bell" />
            {notifCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 bg-brand-orange text-white text-[11px] font-bold w-5 h-5 rounded-full flex items-center justify-center border-2 border-white">
                {notifCount}
              </span>
            )}
          </button>
        </header>

        {/* Scrollable content */}
        <div className="flex-1 overflow-y-auto p-5">

          {/* ── KPI Cards ── */}
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 mb-4">
            <StatCard icon="fa-solid fa-layer-group"      color="orange" value={content.length} label={t('adminDash.kpiContents')} />
            <StatCard icon="fa-solid fa-user-group"       color="blue"   value={users.length}   label={t('adminDash.kpiUsers')} />
            <StatCard icon="fa-solid fa-circle-check"     color="green"  value={activeUsers}    label={t('adminDash.kpiActive')} />
            <StatCard icon="fa-regular fa-hourglass-half" color="gray"   value={notifCount}     label={t('adminDash.kpiPending')} onClick={() => setView('registrations')} />
          </div>

          {/* ══ VIEW : BIBLIOTHÈQUE ══ */}
          {view === 'content' && (
            <Section
              title="Bibliothèque de contenus"
              badge={
                <span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">
                  <i className="fa-solid fa-chart-pie text-xs" /> {content.length} éléments
                </span>
              }
            >
              {/* Filters */}
              <div className="flex flex-wrap items-center gap-3 mb-5">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Type :</span>
                  {(['all', 'video', 'audio'] as const).map(t => (
                    <button key={t} type="button" onClick={() => setLibTypeFilter(t)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all
                        ${libTypeFilter === t ? 'bg-brand-orange text-white border-brand-orange' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
                      {t === 'all' ? 'Tous' : t === 'video' ? ' Vidéo' : ' Audio'}
                    </button>
                  ))}
                </div>
                <div className="flex items-center gap-2 ml-4">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Langue :</span>
                  {(['all', 'fr', 'ar', 'tn'] as const).map(l => (
                    <button key={l} type="button" onClick={() => setLibLangFilter(l)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all
                        ${libLangFilter === l ? 'bg-brand-orange text-white border-brand-orange' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
                      {l === 'all' ? 'Toutes' : l === 'fr' ? ' FR' : l === 'ar' ? ' AR' : '️ TN'}
                    </button>
                  ))}
                </div>
              </div>

              {loading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : (() => {
                const filtered = content.filter(item => {
                  const typeOk = libTypeFilter === 'all' || item.type === libTypeFilter;
                  const langOk = libLangFilter === 'all' || (item as any).language === libLangFilter;
                  return typeOk && langOk;
                });
                return filtered.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                    <i className="fa-solid fa-inbox text-5xl" />
                    <p className="font-medium">Aucun contenu correspondant.</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {filtered.map(item => (
                      <ContentCard key={item.id} content={item}
                        onEdit={setEditingContent}
                        onDelete={c => { setDeletingContentId(c.id); setDeletingTitle(c.title); }} />
                    ))}
                  </div>
                );
              })()}
            </Section>
          )}

          {/* ══ VIEW : IMPORTER ══ */}
          {view === 'upload' && (
            <Section
              title="Nouveau contenu"
              badge={
                <span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">
                  <i className="fa-solid fa-lock text-xs" /> Espace sécurisé
                </span>
              }
            >
              {/* Type tabs — Video + Audio only */}
              <div className="flex gap-4 mb-6">
                {([['video', 'fa-solid fa-video', 'Vidéo'], ['audio', 'fa-solid fa-music', 'Audio']] as const).map(([t, fa, label]) => (
                  <button key={t} type="button"
                    className={`flex items-center gap-2.5 px-5 py-3 rounded-xl font-semibold text-sm border transition-all
                      ${uploadForm.type === t
                        ? 'bg-orange-50 border-brand-orange text-orange-700'
                        : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                    onClick={() => setUploadForm(p => ({ ...p, type: t }))}
                  >
                    <i className={fa} /> {label}
                  </button>
                ))}
              </div>

              <form onSubmit={handleUploadSubmit} className="space-y-6">
                {/* Drop zone */}
                <div>
                  <label className={labelCls}>Fichier source *</label>
                  <label className="flex flex-col items-center justify-center gap-3 border-2 border-dashed border-slate-200 rounded-2xl p-10 bg-slate-50 cursor-pointer hover:border-brand-orange hover:bg-orange-50/30 transition-all">
                    <i className="fa-solid fa-cloud-arrow-up text-4xl text-brand-orange" />
                    <span className="font-semibold text-slate-700">Cliquez pour uploader un fichier</span>
                    <span className="text-sm text-slate-400">MP4, MP3, WAV, OGG — Max 50 MB</span>
                    {uploadForm.file && <span className="text-sm font-medium text-emerald-600"><i className="fa-solid fa-circle-check mr-1" />{uploadForm.file.name}</span>}
                    <input type="file" className="hidden" accept="video/*,audio/*" onChange={e => { if (e.target.files?.[0]) setUploadForm(p => ({ ...p, file: e.target.files![0] })); }} required />
                  </label>
                </div>

                {/* Titre à 50% de largeur */}
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className={labelCls}>Titre du contenu *</label>
                    <input type="text" name="title" value={uploadForm.title} onChange={handleUploadChange} placeholder="Ex: Apprentissage des couleurs" className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Langue</label>
                    <select name="language" value={uploadForm.language || 'fr'} onChange={handleUploadChange} className={inputCls}>
                      <option value="fr"> Français (FR)</option>
                      <option value="ar"> Arabe (AR)</option>
                      <option value="tn">️ Dialecte Tunisien (TN)</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className={labelCls}>Catégorie</label>
                    <input type="text" name="category" value={uploadForm.category} onChange={handleUploadChange} placeholder="Ex: Langage, Motricité" className={inputCls} />
                  </div>
                  <div>
                    <label className={labelCls}>Groupe d'âge</label>
                    <select name="ageGroup" value={uploadForm.ageGroup} onChange={handleUploadChange} className={inputCls}>
                      <option value="3-5">3-5 ans</option>
                      <option value="4-6">4-6 ans</option>
                      <option value="5-8">5-8 ans</option>
                      <option value="6-8">6-8 ans</option>
                    </select>
                  </div>
                  <div>
                    <label className={labelCls}>Niveau de difficulté</label>
                    <select name="level" value={uploadForm.level} onChange={handleUploadChange} className={inputCls}>
                      <option value="1">1 — Facile</option>
                      <option value="2">2 — Moyen</option>
                      <option value="3">3 — Difficile</option>
                    </select>
                  </div>
                  <div>
                    <label className={labelCls}>Emoji</label>
                    <input type="text" name="emoji" value={uploadForm.emoji || ''} onChange={handleUploadChange} placeholder="" maxLength={2} className={inputCls} />
                  </div>
                  {uploadForm.type === 'video' && (
                    <div>
                      <label className={labelCls}>Durée estimée</label>
                      <input type="text" name="duration" value={uploadForm.duration || ''} onChange={handleUploadChange} placeholder="Ex: 5 min" className={inputCls} />
                    </div>
                  )}
                  <div>
                    <label className={labelCls}>Couleur catégorie</label>
                    <input type="color" name="categoryColor" value={uploadForm.categoryColor || '#f97316'} onChange={handleUploadChange} className="h-[46px] w-full rounded-xl border border-slate-200 cursor-pointer p-1" />
                  </div>
                </div>

                <div>
                  <label className={labelCls}>Description (optionnelle)</label>
                  <textarea name="description" value={uploadForm.description} onChange={handleUploadChange} placeholder="Décrivez le but de ce contenu…" rows={4} className={inputCls} />
                </div>

                <div className="flex justify-end">
                  <button type="submit" disabled={loading}
                    className="flex items-center gap-2 bg-brand-orange hover:bg-orange-700 disabled:opacity-60 text-white font-semibold px-8 py-3.5 rounded-xl shadow-lg shadow-brand-orange/20 transition-all hover:-translate-y-0.5">
                    {loading
                      ? <><span className="w-4 h-4 rounded-full border-2 border-white/30 border-t-white animate-spin" /> Upload en cours…</>
                      : <>Publier le contenu <i className="fa-solid fa-arrow-right ml-1" /></>
                    }
                  </button>
                </div>
              </form>
            </Section>
          )}

          {/* ══ VIEW : UTILISATEURS ══ */}
          {view === 'users' && (<>
            <Section title="Ajouter un utilisateur">
              <form onSubmit={handleCreateUser} className="space-y-5">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <div>
                    <label className={labelCls}>Adresse e-mail *</label>
                    <input type="email" value={createForm.email} onChange={e => setCreateForm(p => ({ ...p, email: e.target.value }))} placeholder="exemple@email.com" className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Nom d'utilisateur *</label>
                    <input type="text" value={createForm.name} onChange={e => setCreateForm(p => ({ ...p, name: e.target.value }))} placeholder="Prénom Nom" className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Mot de passe temporaire *</label>
                    <input type="password" value={createForm.password} onChange={e => setCreateForm(p => ({ ...p, password: e.target.value }))} placeholder="Min. 6 caractères" minLength={6} className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Rôle attribué</label>
                    <select value={createForm.role} onChange={e => setCreateForm(p => ({ ...p, role: e.target.value as UserRole }))} className={inputCls}>
                      <option value="parent">Compte Parent</option>
                      <option value="professional">Professionnel de santé</option>
                      <option value="admin">Administrateur</option>
                    </select>
                  </div>
                </div>
                <button type="submit" disabled={actLoading}
                  className="flex items-center gap-2 bg-brand-orange hover:bg-orange-700 disabled:opacity-60 text-white font-semibold px-6 py-3 rounded-xl shadow-md shadow-brand-orange/20 transition-all">
                  {actLoading ? 'Création…' : <><i className="fa-solid fa-user-plus" /> Créer le compte</>}
                </button>
              </form>
            </Section>

            <Section
              title="Annuaire des membres"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{users.length} inscrits</span>}
            >
              {users.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-16 text-slate-400 gap-3">
                  <i className="fa-solid fa-users text-4xl" />
                  <p className="font-medium">Aucun utilisateur</p>
                </div>
              ) : (
                <div className="overflow-x-auto -mx-8 -mb-8">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-slate-100">
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Utilisateur</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Contact</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Rôle</th>
                        <th className="text-right px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map(u => (
                        <tr key={u.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                          <td className="px-8 py-5">
                            {editId === u.id && editForm
                              ? <input type="text" value={editForm.name} onChange={e => setEditForm(p => p ? { ...p, name: e.target.value } : p)} className={`${inputCls} py-2`} />
                              : (
                                <div className="flex items-center gap-3">
                                  <div className="w-10 h-10 rounded-full bg-brand-orange flex items-center justify-center font-bold text-white text-sm shrink-0">
                                    {u.name.charAt(0).toUpperCase()}
                                  </div>
                                  <span className="font-semibold text-slate-800">{u.name}</span>
                                </div>
                              )
                            }
                          </td>
                          <td className="px-8 py-5 text-slate-500">
                            {editId === u.id && editForm
                              ? <input type="email" value={editForm.email} onChange={e => setEditForm(p => p ? { ...p, email: e.target.value } : p)} className={`${inputCls} py-2`} />
                              : u.email
                            }
                          </td>
                          <td className="px-8 py-5">
                            {editId === u.id && editForm
                              ? (
                                <select value={editForm.role} onChange={e => setEditForm(p => p ? { ...p, role: e.target.value as UserRole } : p)} className={`${inputCls} py-2`}>
                                  <option value="parent">Parent</option>
                                  <option value="professional">Professionnel</option>
                                  <option value="admin">Admin</option>
                                </select>
                              ) : (
                                <span className={`inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-sm font-semibold ${ROLE_COLOR[u.role] || 'bg-slate-100 text-slate-500'}`}>
                                  <i className={ROLE_FA[u.role]} /> {u.role}
                                </span>
                              )
                            }
                          </td>
                          <td className="px-8 py-5 text-right">
                            <div className="flex items-center justify-end gap-2">
                              {editId === u.id ? (<>
                                <button onClick={() => handleEditSaveUser(u)} disabled={actLoading}
                                  className="px-4 py-2 bg-brand-orange text-white text-sm font-semibold rounded-lg hover:bg-orange-700 transition">
                                  <i className="fa-solid fa-check mr-1" />Sauvegarder
                                </button>
                                <button onClick={() => { setEditId(null); setEditForm(null); }}
                                  className="px-4 py-2 bg-white border border-slate-200 text-slate-600 text-sm font-semibold rounded-lg hover:bg-slate-50 transition">
                                  Annuler
                                </button>
                              </>) : (<>
                                <button onClick={() => { setEditId(u.id); setEditForm({ name: u.name, email: u.email, role: u.role }); }} disabled={actLoading}
                                  className="w-9 h-9 border border-slate-200 bg-white rounded-lg text-slate-600 flex items-center justify-center hover:bg-slate-50 transition">
                                  <i className="fa-solid fa-pen text-sm" />
                                </button>
                                <button onClick={() => handleDeleteUser(u)} disabled={actLoading}
                                  className="w-9 h-9 border border-red-100 bg-white rounded-lg text-red-500 flex items-center justify-center hover:bg-red-50 transition">
                                  <i className="fa-regular fa-trash-can text-sm" />
                                </button>
                              </>)}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Section>
          </>)}

          {/* ══ VIEW : RELATIONS ══ */}
          {view === 'relations' && (
            <Section
              title="Relations Parent ↔ Professionnel"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{relations.length} liaison(s)</span>}
            >
              {monitorLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : relations.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <i className="fa-solid fa-link text-5xl" />
                  <p className="font-medium">Aucune relation enregistrée.</p>
                </div>
              ) : (
                  <div className="overflow-x-auto -mx-8 -mb-8">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-slate-100">
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Parent</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Professionnel</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Statut</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Date</th>
                        <th className="text-right px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {relations.map(r => (
                        <tr key={r.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                          <td className="px-8 py-4">
                            <p className="font-semibold text-slate-800">{r.parent_name}</p>
                            <p className="text-xs text-slate-400">{r.parent_email}</p>
                          </td>
                          <td className="px-8 py-4">
                            <p className="font-semibold text-slate-800">{r.professional_name}</p>
                            <p className="text-xs text-slate-400">{r.professional_email}</p>
                          </td>
                          <td className="px-8 py-4">
                            <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-bold ${
                              r.status === 'active'  ? 'bg-emerald-100 text-emerald-700' :
                              r.status === 'pending' ? 'bg-amber-100 text-amber-700'    :
                                                       'bg-red-100 text-red-600'
                            }`}>{r.status}</span>
                          </td>
                          <td className="px-8 py-4 text-slate-500 text-sm">
                            {new Date(r.invited_at).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' })}
                          </td>
                          <td className="px-8 py-4 text-right">
                            <button onClick={() => handleDeleteRelation(r.id)}
                              className="w-9 h-9 border border-red-100 bg-white rounded-lg text-red-500 flex items-center justify-center hover:bg-red-50 transition ml-auto"
                              title="Supprimer cette relation">
                              <i className="fa-regular fa-trash-can text-sm" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Section>
          )}

          {/* ══ VIEW : MESSAGES ══ */}
          {view === 'messages' && (
            <Section
              title="Tous les messages"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{adminMessages.length} message(s)</span>}
            >
              {/* Filters */}
              <div className="flex flex-wrap items-center gap-3 mb-5">
                <input
                  type="date"
                  value={msgDateFilter}
                  onChange={e => setMsgDateFilter(e.target.value)}
                  className="px-3 py-2 border border-slate-200 rounded-xl text-sm text-slate-700 bg-white focus:outline-none focus:border-brand-orange transition"
                  title="Filtrer par date"
                />
                <input
                  type="text"
                  value={msgNameFilter}
                  onChange={e => setMsgNameFilter(e.target.value)}
                  placeholder="Rechercher par nom…"
                  className="px-3 py-2 border border-slate-200 rounded-xl text-sm text-slate-700 bg-white focus:outline-none focus:border-brand-orange transition w-48"
                />
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Rôle :</span>
                  {(['all', 'parent', 'professional'] as const).map(r => (
                    <button key={r} type="button" onClick={() => setMsgRoleFilter(r)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all
                        ${msgRoleFilter === r ? 'bg-brand-orange text-white border-brand-orange' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
                      {r === 'all' ? 'Tous' : r === 'parent' ? '‍‍ Parent' : ' Professionnel'}
                    </button>
                  ))}
                </div>
                {(msgDateFilter || msgNameFilter || msgRoleFilter !== 'all') && (
                  <button onClick={() => { setMsgDateFilter(''); setMsgNameFilter(''); setMsgRoleFilter('all'); }}
                    className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-red-50 text-red-500 border border-red-200 hover:bg-red-100 transition">
                    <i className="fa-solid fa-xmark mr-1" /> Réinitialiser
                  </button>
                )}
              </div>

              {monitorLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : (() => {
                const filtered = adminMessages.filter(m => {
                  const dateOk = !msgDateFilter || m.created_at.startsWith(msgDateFilter);
                  const nameOk = !msgNameFilter || m.sender_name.toLowerCase().includes(msgNameFilter.toLowerCase()) || m.receiver_name.toLowerCase().includes(msgNameFilter.toLowerCase());
                  const roleOk = msgRoleFilter === 'all' || m.sender_role === msgRoleFilter || m.receiver_role === msgRoleFilter;
                  return dateOk && nameOk && roleOk;
                });
                return filtered.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                    <i className="fa-solid fa-comments text-5xl" />
                    <p className="font-medium">Aucun message correspondant.</p>
                  </div>
                ) : (
                  <div className="overflow-x-auto -mx-8 -mb-8">
                    <table className="w-full">
                      <thead>
                        <tr className="border-b border-slate-100">
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Expéditeur</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Destinataire</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Enfant</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Contenu</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Date</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filtered.map(m => (
                          <tr key={m.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                            <td className="px-8 py-4">
                              <p className="font-semibold text-slate-800">{m.sender_name}</p>
                              <p className="text-xs text-slate-400 capitalize">{m.sender_role === 'professional' ? ' Professionnel' : '‍‍ Parent'}</p>
                            </td>
                            <td className="px-8 py-4">
                              <p className="font-semibold text-slate-800">{m.receiver_name}</p>
                              <p className="text-xs text-slate-400 capitalize">{m.receiver_role === 'professional' ? ' Professionnel' : '‍‍ Parent'}</p>
                            </td>
                            <td className="px-8 py-4 text-slate-600 text-sm">{m.child_name}</td>
                            <td className="px-8 py-4 text-slate-600 text-sm max-w-xs truncate">{m.content}</td>
                            <td className="px-8 py-4 text-slate-500 text-sm whitespace-nowrap">
                              {new Date(m.created_at).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' })}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                );
              })()}
            </Section>
          )}

          {/* ══ VIEW : NOTES CLINIQUES ══ */}
          {view === 'notes' && (
            <Section
              title="Toutes les notes cliniques"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{adminNotes.length} note(s)</span>}
            >
              {monitorLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : adminNotes.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <i className="fa-solid fa-notes-medical text-5xl" />
                  <p className="font-medium">Aucune note clinique enregistrée.</p>
                </div>
              ) : (
                <div className="flex flex-col gap-4">
                  {adminNotes.map(n => (
                    <div key={n.id} className="bg-slate-50 border border-slate-100 border-l-4 border-l-brand-orange rounded-xl p-5">
                      <div className="flex items-center justify-between mb-2 flex-wrap gap-2">
                        <div className="flex items-center gap-2">
                          <i className="fa-solid fa-stethoscope text-brand-orange text-sm" />
                          <span className="font-bold text-slate-800 text-sm">Dr. {n.professional_name}</span>
                          <span className="text-xs text-slate-400">{n.professional_email}</span>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="inline-flex items-center gap-1.5 bg-orange-100 text-orange-700 px-3 py-1 rounded-full text-xs font-semibold">
                            <i className="fa-solid fa-baby text-[10px]" /> {n.child_name}
                          </span>
                          <span className="text-xs text-slate-400">
                            {new Date(n.date).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' })}
                          </span>
                        </div>
                      </div>
                      <p className="text-slate-600 text-sm leading-relaxed">{n.content}</p>
                    </div>
                  ))}
                </div>
              )}
            </Section>
          )}

          {/* ══ VIEW : DEMANDES ══ */}
          {view === 'registrations' && (            <Section
              title="Demandes d'inscription"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{pending.length} en attente</span>}
            >
              {pending.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 gap-5">
                  <div className="w-20 h-20 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-4xl">
                    <i className="fa-solid fa-check" />
                  </div>
                  <div className="text-center">
                    <h3 className="text-xl font-bold text-slate-800 mb-1">Tout est à jour !</h3>
                    <p className="text-slate-500">Vous n'avez aucune demande d'inscription en attente.</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  {pending.map(reg => (
                    <div key={reg.id} className="flex items-center gap-5 p-5 bg-slate-50 rounded-xl border border-slate-100">
                      <div className="w-12 h-12 rounded-full bg-brand-orange flex items-center justify-center font-bold text-white text-lg shrink-0">
                        {reg.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-slate-900">{reg.name}</p>
                        <p className="text-sm text-slate-500">{reg.email}</p>
                        {reg.created_at && (
                          <p className="text-xs text-slate-400 mt-0.5">
                            {new Date(reg.created_at).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
                          </p>
                        )}
                      </div>
                      <span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-3 py-1.5 rounded-full text-xs font-semibold shrink-0">
                        <i className="fa-solid fa-house-user" /> Parent
                      </span>
                      <div className="flex gap-2 shrink-0">
                        <button onClick={() => handleApprove(reg.id)} disabled={actLoading}
                          className="flex items-center gap-1.5 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-semibold rounded-lg transition">
                          <i className="fa-solid fa-check" /> Accepter
                        </button>
                        <button onClick={() => handleReject(reg.id)} disabled={actLoading}
                          className="flex items-center gap-1.5 px-4 py-2 bg-white border border-red-200 text-red-500 hover:bg-red-50 text-sm font-semibold rounded-lg transition">
                          <i className="fa-solid fa-xmark" /> Refuser
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Section>
          )}

        </div>
      </div>

      {/* ── Modals ── */}
      <EditContentModal content={editingContent} isOpen={!!editingContent} onClose={() => setEditingContent(null)} onSave={handleEditSave} isLoading={loading} />
      <DeleteContentModal contentId={deletingContentId} contentTitle={deletingTitle} isOpen={!!deletingContentId} onClose={() => { setDeletingContentId(null); setDeletingTitle(''); }} onConfirm={handleDeleteConfirm} isLoading={loading} />

      {/* ── Toasts ── */}
      <ToastStack toasts={toasts} onRemove={removeToast} />

    </div>
  );
};

// ============================================================================
// ADMIN PANEL — Design matching adminIndex.html (orange theme + FontAwesome)
// ============================================================================

import React, { useState, useEffect } from 'react';

import { useTranslation } from 'react-i18next';
import { useAuth } from '../features/auth/hooks/useAuth';
import api from '../lib/api';
import { ContentItem, ContentFormData, User } from '../features/content/types/content.types';
import { ContentCard } from '../features/admin/components/ContentCard';
import { EditContentModal } from '../features/admin/components/EditContentModal';
import { DeleteContentModal } from '../features/admin/components/DeleteContentModal';
import { StatCard, Section, useToast, ToastStack } from '../components';
import LanguageSwitcher from '../components/ui/LanguageSwitcher';

// ── Types ──────────────────────────────────────────────────────────────────
type ViewType = 'content' | 'upload' | 'users' | 'registrations' | 'relations' | 'messages' | 'notes';
type UserRole = 'admin' | 'parent' | 'professional';
interface UserFormState { name: string; email: string; password: string; role: UserRole; }
interface ApiResult<T> { success: boolean; data: T; message?: string; }

interface RelationRow {
  id: number; status: string; invited_at: string;
  parent_name: string; parent_email: string;
  professional_name: string; professional_email: string;
}
interface MessageRow {
  id: number; content: string; created_at: string; is_read: number;
  sender_name: string; sender_role: string;
  receiver_name: string; receiver_role: string;
  child_name: string;
}
interface NoteRow {
  id: number; content: string; date: string;
  professional_name: string; professional_email: string;
  child_name: string;
}


// ── Nav config ─────────────────────────────────────────────────────────────
const NAV_IDS = [
  { id: 'content',       fa: 'fa-solid fa-swatchbook',          key: 'navLibrary'       },
  { id: 'upload',        fa: 'fa-solid fa-cloud-arrow-up',       key: 'navUpload'        },
  { id: 'users',         fa: 'fa-solid fa-users',                key: 'navUsers'         },
  { id: 'registrations', fa: 'fa-solid fa-bell',                 key: 'navRegistrations' },
  { id: 'relations',     fa: 'fa-solid fa-link',                 key: 'navRelations'     },
  { id: 'messages',      fa: 'fa-solid fa-comments',             key: 'navMessages'      },
  { id: 'notes',         fa: 'fa-solid fa-notes-medical',        key: 'navNotes'         },
] as const;

const ROLE_FA: Record<string, string> = {
  admin:        'fa-solid fa-shield-halved',
  parent:       'fa-solid fa-house-user',
  professional: 'fa-solid fa-stethoscope',
};
const ROLE_COLOR: Record<string, string> = {
  admin:        'bg-purple-100 text-purple-700',
  parent:       'bg-orange-100 text-orange-700',
  professional: 'bg-blue-100 text-blue-700',
};

// ── Section wrapper (uses shared Section from components) ───────────────

// ── Input / Select helpers ─────────────────────────────────────────────────
const inputCls = 'w-full px-4 py-3.5 border border-slate-200 rounded-xl text-slate-900 placeholder-slate-400 bg-white text-[15px] focus:outline-none focus:ring-4 focus:ring-brand-orange/10 focus:border-brand-orange transition-all';
const labelCls = 'block text-sm font-semibold text-slate-800 mb-2';

// ── Main Component ─────────────────────────────────────────────────────────
export const AdminPanel = (): JSX.Element => {
  const { logout, user } = useAuth();
  const { toasts, add: toast, remove: removeToast } = useToast();
  const { t } = useTranslation();

  const [view,     setView]     = useState<ViewType>('content');
  const [content,  setContent]  = useState<ContentItem[]>([]);
  const [users,    setUsers]    = useState<User[]>([]);
  const [pending,  setPending]  = useState<User[]>([]);
  const [notifCount, setNotifCount] = useState(0);
  const [loading,  setLoading]  = useState(false);
  const [actLoading, setActLoading] = useState(false);

  // ── Admin monitoring state ─────────────────────────────────────────────
  const [relations,     setRelations]     = useState<RelationRow[]>([]);
  const [adminMessages, setAdminMessages] = useState<MessageRow[]>([]);
  const [adminNotes,    setAdminNotes]    = useState<NoteRow[]>([]);
  const [monitorLoading, setMonitorLoading] = useState(false);

  const [createForm, setCreateForm] = useState<UserFormState>({ name: '', email: '', password: '', role: 'parent' });
  const [editId,     setEditId]     = useState<number | null>(null);
  const [editForm,   setEditForm]   = useState<Omit<UserFormState, 'password'> | null>(null);

  const [editingContent,    setEditingContent]    = useState<ContentItem | null>(null);
  const [deletingContentId, setDeletingContentId] = useState<number | null>(null);
  const [deletingTitle,     setDeletingTitle]     = useState('');

  const [uploadForm, setUploadForm] = useState<ContentFormData>({
    title: '', type: 'video', description: '', category: '',
    categoryColor: '#f97316', emoji: '', duration: '',
    steps: 5, minutes: 15, emojiColor: '#d1fae5',
    ageGroup: '4-6', level: '1', language: 'fr', file: null,
  });

  // ── Filters state ──────────────────────────────────────────────────────────
  const [libTypeFilter, setLibTypeFilter]   = useState<'all' | 'video' | 'audio' | 'activity'>('all');
  const [libLangFilter, setLibLangFilter]   = useState<'all' | 'fr' | 'ar' | 'tn'>('all');
  const [msgDateFilter, setMsgDateFilter]   = useState('');
  const [msgNameFilter, setMsgNameFilter]   = useState('');
  const [msgRoleFilter, setMsgRoleFilter]   = useState<'all' | 'parent' | 'professional'>('all');

  // ── Data fetchers ──────────────────────────────────────────────────────
  const fetchContent = async () => { const { data } = await api.get<ApiResult<ContentItem[]>>('/api/content'); if (data.success) setContent(data.data); };
  const fetchUsers   = async () => { const { data } = await api.get<ApiResult<User[]>>('/api/users'); if (data.success) setUsers(data.data); };
  const fetchPending = async () => { try { const { data } = await api.get<ApiResult<User[]>>('/api/admin/pending-registrations'); if (data.success) { setPending(data.data); setNotifCount(data.data.length); } } catch { /* silent */ } };

  const fetchRelations = async () => { try { setMonitorLoading(true); const { data } = await api.get<ApiResult<RelationRow[]>>('/api/admin/relations'); if (data.success) setRelations(data.data); } catch { /* silent */ } finally { setMonitorLoading(false); } };
  const fetchAdminMessages = async () => { try { setMonitorLoading(true); const { data } = await api.get<ApiResult<MessageRow[]>>('/api/admin/messages'); if (data.success) setAdminMessages(data.data); } catch { /* silent */ } finally { setMonitorLoading(false); } };
  const fetchAdminNotes    = async () => { try { setMonitorLoading(true); const { data } = await api.get<ApiResult<NoteRow[]>>('/api/admin/notes'); if (data.success) setAdminNotes(data.data); } catch { /* silent */ } finally { setMonitorLoading(false); } };

  const handleDeleteRelation = async (id: number) => {
    if (!window.confirm('Supprimer définitivement cette relation ? Le professionnel n\'aura plus accès aux données de ce parent.')) return;
    try {
      const { data } = await api.delete<ApiResult<null>>(`/api/admin/relations/${id}`);
      if (data.success) { toast('Relation supprimée ✓'); await fetchRelations(); }
      else toast(data.message || 'Erreur', 'error');
    } catch { toast('Erreur réseau.', 'error'); }
  };

  useEffect(() => { setLoading(true); Promise.all([fetchContent(), fetchUsers()]).finally(() => setLoading(false)); }, []);
  useEffect(() => { fetchPending(); const t = setInterval(fetchPending, 30000); return () => clearInterval(t); }, []);
  useEffect(() => {
    if (view === 'relations') fetchRelations();
    else if (view === 'messages') fetchAdminMessages();
    else if (view === 'notes') fetchAdminNotes();
  }, [view]);

  // ── Handlers ──────────────────────────────────────────────────────────
  const handleApprove = async (id: number) => { try { setActLoading(true); await api.post(`/api/admin/approve-registration/${id}`); await Promise.all([fetchPending(), fetchUsers()]); toast('Inscription acceptée ✓'); } catch { toast("Erreur lors de l'acceptation", 'error'); } finally { setActLoading(false); } };
  const handleReject  = async (id: number) => { try { setActLoading(true); await api.post(`/api/admin/reject-registration/${id}`); await fetchPending(); toast('Demande refusée'); } catch { toast('Erreur lors du refus', 'error'); } finally { setActLoading(false); } };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!createForm.name.trim() || !createForm.email.trim() || !createForm.password.trim()) { toast('Tous les champs sont requis', 'error'); return; }
    try {
      setActLoading(true);
      const { data } = await api.post<ApiResult<User>>('/api/users', { name: createForm.name.trim(), email: createForm.email.trim().toLowerCase(), password: createForm.password, role: createForm.role });
      if (!data.success) { toast(data.message || 'Erreur création', 'error'); return; }
      setCreateForm({ name: '', email: '', password: '', role: 'parent' });
      await fetchUsers(); toast('Utilisateur créé ✓');
    } catch { toast('Erreur lors de la création', 'error'); } finally { setActLoading(false); }
  };

  const handleEditSaveUser = async (u: User) => {
    if (!editForm) return;
    try {
      setActLoading(true);
      const { data } = await api.put<ApiResult<User>>(`/api/users/${u.id}`, { name: editForm.name.trim(), email: editForm.email.trim().toLowerCase(), role: editForm.role, is_active: u.is_active });
      if (!data.success) { toast(data.message || 'Erreur mise à jour', 'error'); return; }
      setEditId(null); setEditForm(null); await fetchUsers(); toast('Utilisateur mis à jour ✓');
    } catch { toast('Erreur mise à jour', 'error'); } finally { setActLoading(false); }
  };

  const handleDeleteUser = async (u: User) => {
    if (!window.confirm(`Supprimer définitivement ${u.name} ?`)) return;
    try { setActLoading(true); const { data } = await api.delete<ApiResult<null>>(`/api/users/${u.id}`); if (!data.success) { toast(data.message || 'Erreur', 'error'); return; } await fetchUsers(); toast(`${u.name} supprimé`); } catch { toast('Erreur suppression', 'error'); } finally { setActLoading(false); }
  };

  const handleUploadChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    setUploadForm(p => ({ ...p, [name]: type === 'number' ? (value ? parseInt(value) : undefined) : value }));
  };

  const handleUploadSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!uploadForm.file || !uploadForm.title) { toast('Fichier et titre requis', 'error'); return; }
    try {
      setLoading(true);
      const fd = new FormData();
      fd.append('file', uploadForm.file); fd.append('title', uploadForm.title); fd.append('type', uploadForm.type);
      fd.append('description', uploadForm.description || ''); fd.append('category', uploadForm.category || '');
      fd.append('category_color', uploadForm.categoryColor || '#f97316'); fd.append('emoji', uploadForm.emoji || '');
      fd.append('age_group', uploadForm.ageGroup || '4-6'); fd.append('level', uploadForm.level?.toString() || '1');
      fd.append('language', uploadForm.language || 'fr');
      if (uploadForm.type === 'video' && uploadForm.duration) fd.append('duration', uploadForm.duration);
      if (uploadForm.type === 'activity') { fd.append('steps', (uploadForm.steps || 5).toString()); fd.append('minutes', (uploadForm.minutes || 15).toString()); fd.append('emoji_color', uploadForm.emojiColor || '#d1fae5'); }
      const { data } = await api.post<ApiResult<ContentItem>>('/api/content/upload', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      if (data.success) { toast('Contenu uploadé ✓'); setUploadForm({ title: '', type: 'video', description: '', category: '', categoryColor: '#f97316', emoji: '', duration: '', steps: 5, minutes: 15, emojiColor: '#d1fae5', ageGroup: '4-6', level: '1', language: 'fr', file: null }); await fetchContent(); }
      else toast(data.message || 'Erreur upload', 'error');
    } catch (err) { toast(err instanceof Error ? err.message : 'Erreur upload', 'error'); } finally { setLoading(false); }
  };

  const handleEditSave = async (contentId: number, formData: ContentFormData) => {
    try { setLoading(true); const { data } = await api.put<ApiResult<ContentItem>>(`/api/content/${contentId}`, { title: formData.title, type: formData.type, category: formData.category, category_color: formData.categoryColor, emoji: formData.emoji, duration: formData.duration, steps: formData.steps, minutes: formData.minutes, emoji_color: formData.emojiColor, description: formData.description, age_group: formData.ageGroup, level: formData.level }); if (data.success) { toast('Contenu mis à jour ✓'); setEditingContent(null); await fetchContent(); } else toast('Erreur: ' + data.message, 'error'); } catch { toast('Erreur mise à jour', 'error'); } finally { setLoading(false); }
  };

  const handleDeleteConfirm = async () => {
    if (!deletingContentId) return;
    try { setLoading(true); const { data } = await api.delete<ApiResult<null>>(`/api/content/${deletingContentId}`); if (data.success) { toast('Contenu supprimé'); setDeletingContentId(null); setDeletingTitle(''); await fetchContent(); } else toast('Erreur: ' + data.message, 'error'); } catch { toast('Erreur suppression', 'error'); } finally { setLoading(false); }
  };

  const activeUsers    = users.filter(u => !!u.is_active).length;
  const adminInitial   = user?.name?.charAt(0).toUpperCase() || 'A';
  const currentNavItem = NAV_IDS.find(n => n.id === view);

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const closeSidebar = () => setSidebarOpen(false);

  // ── Render ─────────────────────────────────────────────────────────────
  return (
    <div className="font-sans antialiased flex h-screen overflow-hidden bg-slate-50 animate-page-in">

      {/* Mobile overlay */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={closeSidebar} />
      )}

      {/* ══════════════ SIDEBAR ══════════════ */}
      <aside
        className={`fixed inset-y-0 left-0 md:relative md:translate-x-0 w-[280px] relative flex flex-col z-30 md:z-10 shrink-0 transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}
        style={{
          background: '#F97316',
          backgroundImage: 'linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px)',
          backgroundSize: '20px 20px',
          boxShadow: '4px 0 15px rgba(249,115,22,0.2)',
        }}
      >
        {/* Brand */}
        <div className="flex items-center gap-4 px-6 py-4">
          <div className="w-12 h-12 bg-white text-brand-orange rounded-xl flex items-center justify-center text-2xl shadow-sm shrink-0">
            <i className="fa-solid fa-puzzle-piece" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-white tracking-tight leading-none">AIDAA</h2>
            <span className="text-[11px] text-white/80 font-medium uppercase tracking-widest">{t('adminDash.title')}</span>
          </div>
        </div>

        {/* Admin profile card — top */}
        <div className="px-5 pb-2 shrink-0">
          <div className="flex items-center gap-3 bg-white/10 border border-white/20 rounded-xl p-3">
            <div className="w-9 h-9 rounded-full bg-white flex items-center justify-center font-bold text-brand-orange text-sm shrink-0">
              {adminInitial}
            </div>
            <div className="min-w-0">
              <p className="text-sm font-semibold text-white truncate">{user?.name || 'Admin'}</p>
              <p className="text-xs text-white/80">{t('adminDash.administrator')}</p>
            </div>
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 px-5 flex flex-col gap-2">
          {NAV_IDS.map(n => (
            <button key={n.id}
              className={`flex items-center w-full px-5 py-3.5 rounded-xl font-semibold text-[15px] border transition-all
                ${view === n.id
                  ? 'bg-white text-brand-orange shadow-md border-transparent'
                  : 'text-white border-transparent hover:bg-white/15 hover:border-white/20'}`}
              onClick={() => { setView(n.id as ViewType); closeSidebar(); }}
            >
              <i className={`${n.fa} w-6 mr-3 text-lg ${view === n.id ? 'text-brand-orange opacity-100' : 'opacity-80'}`} />
              {t(`adminDash.${n.key}`)}
              {n.id === 'registrations' && notifCount > 0 && (
                <span className="ml-auto w-5 h-5 rounded-full bg-white text-brand-orange text-[11px] font-bold flex items-center justify-center">
                  {notifCount}
                </span>
              )}
            </button>
          ))}
        </nav>

        {/* Footer — logout only */}
        <div className="px-5 pb-5 flex flex-col gap-2">
          <div className="flex justify-center">
            <LanguageSwitcher dropDirection="up" />
          </div>
          <button onClick={logout}
            className="w-full flex items-center justify-center gap-2 bg-black/15 hover:bg-black/25 text-white font-semibold py-3 rounded-lg transition-all text-sm">
            {t('adminDash.disconnect')} <i className="fa-solid fa-arrow-right-from-bracket" />
          </button>
        </div>
      </aside>

      {/* ══════════════ MAIN ══════════════════ */}
      <div className="flex-1 flex flex-col overflow-hidden">

        {/* Top header */}
        <header className="h-16 md:h-20 bg-white border-b border-slate-200 flex items-center justify-between px-4 md:px-10 shrink-0">
          <div className="flex items-center gap-3">
            {/* Hamburger — mobile only */}
            <button
              className="md:hidden w-9 h-9 rounded-lg border border-slate-200 bg-white text-slate-600 flex items-center justify-center hover:bg-slate-50 transition"
              onClick={() => setSidebarOpen(v => !v)}
              aria-label="Menu"
            >
              <i className="fa-solid fa-bars" />
            </button>
            <div className="flex items-baseline gap-2">
              <span className="text-sm text-slate-500 font-medium hidden sm:inline">{t('adminDash.breadcrumb')}</span>
              <span className="text-lg md:text-xl font-bold text-slate-900">{currentNavItem ? t(`adminDash.${currentNavItem.key}`) : ''}</span>
            </div>
          </div>
          <button
            className="relative w-11 h-11 rounded-full border border-slate-200 bg-white text-slate-600 flex items-center justify-center hover:bg-slate-50 transition text-lg"
            onClick={() => setView('registrations')}
            title="Demandes en attente"
          >
            <i className="fa-regular fa-bell" />
            {notifCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 bg-brand-orange text-white text-[11px] font-bold w-5 h-5 rounded-full flex items-center justify-center border-2 border-white">
                {notifCount}
              </span>
            )}
          </button>
        </header>

        {/* Scrollable content */}
        <div className="flex-1 overflow-y-auto p-3 sm:p-5">

          {/* ── KPI Cards ── */}
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 mb-4">
            <StatCard icon="fa-solid fa-layer-group"      color="orange" value={content.length} label={t('adminDash.kpiContents')} />
            <StatCard icon="fa-solid fa-user-group"       color="blue"   value={users.length}   label={t('adminDash.kpiUsers')} />
            <StatCard icon="fa-solid fa-circle-check"     color="green"  value={activeUsers}    label={t('adminDash.kpiActive')} />
            <StatCard icon="fa-regular fa-hourglass-half" color="gray"   value={notifCount}     label={t('adminDash.kpiPending')} onClick={() => setView('registrations')} />
          </div>

          {/* ══ VIEW : BIBLIOTHÈQUE ══ */}
          {view === 'content' && (
            <Section
              title="Bibliothèque de contenus"
              badge={
                <span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">
                  <i className="fa-solid fa-chart-pie text-xs" /> {content.length} éléments
                </span>
              }
            >
              {/* Filters */}
              <div className="flex flex-wrap items-center gap-3 mb-5">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Type :</span>
                  {(['all', 'video', 'audio'] as const).map(t => (
                    <button key={t} type="button" onClick={() => setLibTypeFilter(t)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all
                        ${libTypeFilter === t ? 'bg-brand-orange text-white border-brand-orange' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
                      {t === 'all' ? 'Tous' : t === 'video' ? ' Vidéo' : ' Audio'}
                    </button>
                  ))}
                </div>
                <div className="flex items-center gap-2 ml-4">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Langue :</span>
                  {(['all', 'fr', 'ar', 'tn'] as const).map(l => (
                    <button key={l} type="button" onClick={() => setLibLangFilter(l)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all
                        ${libLangFilter === l ? 'bg-brand-orange text-white border-brand-orange' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
                      {l === 'all' ? 'Toutes' : l === 'fr' ? ' FR' : l === 'ar' ? ' AR' : '️ TN'}
                    </button>
                  ))}
                </div>
              </div>

              {loading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : (() => {
                const filtered = content.filter(item => {
                  const typeOk = libTypeFilter === 'all' || item.type === libTypeFilter;
                  const langOk = libLangFilter === 'all' || (item as any).language === libLangFilter;
                  return typeOk && langOk;
                });
                return filtered.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                    <i className="fa-solid fa-inbox text-5xl" />
                    <p className="font-medium">Aucun contenu correspondant.</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {filtered.map(item => (
                      <ContentCard key={item.id} content={item}
                        onEdit={setEditingContent}
                        onDelete={c => { setDeletingContentId(c.id); setDeletingTitle(c.title); }} />
                    ))}
                  </div>
                );
              })()}
            </Section>
          )}

          {/* ══ VIEW : IMPORTER ══ */}
          {view === 'upload' && (
            <Section
              title="Nouveau contenu"
              badge={
                <span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">
                  <i className="fa-solid fa-lock text-xs" /> Espace sécurisé
                </span>
              }
            >
              {/* Type tabs — Video + Audio only */}
              <div className="flex gap-4 mb-6">
                {([['video', 'fa-solid fa-video', 'Vidéo'], ['audio', 'fa-solid fa-music', 'Audio']] as const).map(([t, fa, label]) => (
                  <button key={t} type="button"
                    className={`flex items-center gap-2.5 px-5 py-3 rounded-xl font-semibold text-sm border transition-all
                      ${uploadForm.type === t
                        ? 'bg-orange-50 border-brand-orange text-orange-700'
                        : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                    onClick={() => setUploadForm(p => ({ ...p, type: t }))}
                  >
                    <i className={fa} /> {label}
                  </button>
                ))}
              </div>

              <form onSubmit={handleUploadSubmit} className="space-y-6">
                {/* Drop zone */}
                <div>
                  <label className={labelCls}>Fichier source *</label>
                  <label className="flex flex-col items-center justify-center gap-3 border-2 border-dashed border-slate-200 rounded-2xl p-10 bg-slate-50 cursor-pointer hover:border-brand-orange hover:bg-orange-50/30 transition-all">
                    <i className="fa-solid fa-cloud-arrow-up text-4xl text-brand-orange" />
                    <span className="font-semibold text-slate-700">Cliquez pour uploader un fichier</span>
                    <span className="text-sm text-slate-400">MP4, MP3, WAV, OGG — Max 50 MB</span>
                    {uploadForm.file && <span className="text-sm font-medium text-emerald-600"><i className="fa-solid fa-circle-check mr-1" />{uploadForm.file.name}</span>}
                    <input type="file" className="hidden" accept="video/*,audio/*" onChange={e => { if (e.target.files?.[0]) setUploadForm(p => ({ ...p, file: e.target.files![0] })); }} required />
                  </label>
                </div>

                {/* Titre à 50% de largeur */}
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className={labelCls}>Titre du contenu *</label>
                    <input type="text" name="title" value={uploadForm.title} onChange={handleUploadChange} placeholder="Ex: Apprentissage des couleurs" className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Langue</label>
                    <select name="language" value={uploadForm.language || 'fr'} onChange={handleUploadChange} className={inputCls}>
                      <option value="fr"> Français (FR)</option>
                      <option value="ar"> Arabe (AR)</option>
                      <option value="tn">️ Dialecte Tunisien (TN)</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className={labelCls}>Catégorie</label>
                    <input type="text" name="category" value={uploadForm.category} onChange={handleUploadChange} placeholder="Ex: Langage, Motricité" className={inputCls} />
                  </div>
                  <div>
                    <label className={labelCls}>Groupe d'âge</label>
                    <select name="ageGroup" value={uploadForm.ageGroup} onChange={handleUploadChange} className={inputCls}>
                      <option value="3-5">3-5 ans</option>
                      <option value="4-6">4-6 ans</option>
                      <option value="5-8">5-8 ans</option>
                      <option value="6-8">6-8 ans</option>
                    </select>
                  </div>
                  <div>
                    <label className={labelCls}>Niveau de difficulté</label>
                    <select name="level" value={uploadForm.level} onChange={handleUploadChange} className={inputCls}>
                      <option value="1">1 — Facile</option>
                      <option value="2">2 — Moyen</option>
                      <option value="3">3 — Difficile</option>
                    </select>
                  </div>
                  <div>
                    <label className={labelCls}>Emoji</label>
                    <input type="text" name="emoji" value={uploadForm.emoji || ''} onChange={handleUploadChange} placeholder="" maxLength={2} className={inputCls} />
                  </div>
                  {uploadForm.type === 'video' && (
                    <div>
                      <label className={labelCls}>Durée estimée</label>
                      <input type="text" name="duration" value={uploadForm.duration || ''} onChange={handleUploadChange} placeholder="Ex: 5 min" className={inputCls} />
                    </div>
                  )}
                  <div>
                    <label className={labelCls}>Couleur catégorie</label>
                    <input type="color" name="categoryColor" value={uploadForm.categoryColor || '#f97316'} onChange={handleUploadChange} className="h-[46px] w-full rounded-xl border border-slate-200 cursor-pointer p-1" />
                  </div>
                </div>

                <div>
                  <label className={labelCls}>Description (optionnelle)</label>
                  <textarea name="description" value={uploadForm.description} onChange={handleUploadChange} placeholder="Décrivez le but de ce contenu…" rows={4} className={inputCls} />
                </div>

                <div className="flex justify-end">
                  <button type="submit" disabled={loading}
                    className="flex items-center gap-2 bg-brand-orange hover:bg-orange-700 disabled:opacity-60 text-white font-semibold px-8 py-3.5 rounded-xl shadow-lg shadow-brand-orange/20 transition-all hover:-translate-y-0.5">
                    {loading
                      ? <><span className="w-4 h-4 rounded-full border-2 border-white/30 border-t-white animate-spin" /> Upload en cours…</>
                      : <>Publier le contenu <i className="fa-solid fa-arrow-right ml-1" /></>
                    }
                  </button>
                </div>
              </form>
            </Section>
          )}

          {/* ══ VIEW : UTILISATEURS ══ */}
          {view === 'users' && (<>
            <Section title="Ajouter un utilisateur">
              <form onSubmit={handleCreateUser} className="space-y-5">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <div>
                    <label className={labelCls}>Adresse e-mail *</label>
                    <input type="email" value={createForm.email} onChange={e => setCreateForm(p => ({ ...p, email: e.target.value }))} placeholder="exemple@email.com" className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Nom d'utilisateur *</label>
                    <input type="text" value={createForm.name} onChange={e => setCreateForm(p => ({ ...p, name: e.target.value }))} placeholder="Prénom Nom" className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Mot de passe temporaire *</label>
                    <input type="password" value={createForm.password} onChange={e => setCreateForm(p => ({ ...p, password: e.target.value }))} placeholder="Min. 6 caractères" minLength={6} className={inputCls} required />
                  </div>
                  <div>
                    <label className={labelCls}>Rôle attribué</label>
                    <select value={createForm.role} onChange={e => setCreateForm(p => ({ ...p, role: e.target.value as UserRole }))} className={inputCls}>
                      <option value="parent">Compte Parent</option>
                      <option value="professional">Professionnel de santé</option>
                      <option value="admin">Administrateur</option>
                    </select>
                  </div>
                </div>
                <button type="submit" disabled={actLoading}
                  className="flex items-center gap-2 bg-brand-orange hover:bg-orange-700 disabled:opacity-60 text-white font-semibold px-6 py-3 rounded-xl shadow-md shadow-brand-orange/20 transition-all">
                  {actLoading ? 'Création…' : <><i className="fa-solid fa-user-plus" /> Créer le compte</>}
                </button>
              </form>
            </Section>

            <Section
              title="Annuaire des membres"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{users.length} inscrits</span>}
            >
              {users.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-16 text-slate-400 gap-3">
                  <i className="fa-solid fa-users text-4xl" />
                  <p className="font-medium">Aucun utilisateur</p>
                </div>
              ) : (
                <div className="overflow-x-auto -mx-8 -mb-8">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-slate-100">
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Utilisateur</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Contact</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Rôle</th>
                        <th className="text-right px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map(u => (
                        <tr key={u.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                          <td className="px-8 py-5">
                            {editId === u.id && editForm
                              ? <input type="text" value={editForm.name} onChange={e => setEditForm(p => p ? { ...p, name: e.target.value } : p)} className={`${inputCls} py-2`} />
                              : (
                                <div className="flex items-center gap-3">
                                  <div className="w-10 h-10 rounded-full bg-brand-orange flex items-center justify-center font-bold text-white text-sm shrink-0">
                                    {u.name.charAt(0).toUpperCase()}
                                  </div>
                                  <span className="font-semibold text-slate-800">{u.name}</span>
                                </div>
                              )
                            }
                          </td>
                          <td className="px-8 py-5 text-slate-500">
                            {editId === u.id && editForm
                              ? <input type="email" value={editForm.email} onChange={e => setEditForm(p => p ? { ...p, email: e.target.value } : p)} className={`${inputCls} py-2`} />
                              : u.email
                            }
                          </td>
                          <td className="px-8 py-5">
                            {editId === u.id && editForm
                              ? (
                                <select value={editForm.role} onChange={e => setEditForm(p => p ? { ...p, role: e.target.value as UserRole } : p)} className={`${inputCls} py-2`}>
                                  <option value="parent">Parent</option>
                                  <option value="professional">Professionnel</option>
                                  <option value="admin">Admin</option>
                                </select>
                              ) : (
                                <span className={`inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-sm font-semibold ${ROLE_COLOR[u.role] || 'bg-slate-100 text-slate-500'}`}>
                                  <i className={ROLE_FA[u.role]} /> {u.role}
                                </span>
                              )
                            }
                          </td>
                          <td className="px-8 py-5 text-right">
                            <div className="flex items-center justify-end gap-2">
                              {editId === u.id ? (<>
                                <button onClick={() => handleEditSaveUser(u)} disabled={actLoading}
                                  className="px-4 py-2 bg-brand-orange text-white text-sm font-semibold rounded-lg hover:bg-orange-700 transition">
                                  <i className="fa-solid fa-check mr-1" />Sauvegarder
                                </button>
                                <button onClick={() => { setEditId(null); setEditForm(null); }}
                                  className="px-4 py-2 bg-white border border-slate-200 text-slate-600 text-sm font-semibold rounded-lg hover:bg-slate-50 transition">
                                  Annuler
                                </button>
                              </>) : (<>
                                <button onClick={() => { setEditId(u.id); setEditForm({ name: u.name, email: u.email, role: u.role }); }} disabled={actLoading}
                                  className="w-9 h-9 border border-slate-200 bg-white rounded-lg text-slate-600 flex items-center justify-center hover:bg-slate-50 transition">
                                  <i className="fa-solid fa-pen text-sm" />
                                </button>
                                <button onClick={() => handleDeleteUser(u)} disabled={actLoading}
                                  className="w-9 h-9 border border-red-100 bg-white rounded-lg text-red-500 flex items-center justify-center hover:bg-red-50 transition">
                                  <i className="fa-regular fa-trash-can text-sm" />
                                </button>
                              </>)}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Section>
          </>)}

          {/* ══ VIEW : RELATIONS ══ */}
          {view === 'relations' && (
            <Section
              title="Relations Parent ↔ Professionnel"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{relations.length} liaison(s)</span>}
            >
              {monitorLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : relations.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <i className="fa-solid fa-link text-5xl" />
                  <p className="font-medium">Aucune relation enregistrée.</p>
                </div>
              ) : (
                  <div className="overflow-x-auto -mx-8 -mb-8">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-slate-100">
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Parent</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Professionnel</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Statut</th>
                        <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Date</th>
                        <th className="text-right px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {relations.map(r => (
                        <tr key={r.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                          <td className="px-8 py-4">
                            <p className="font-semibold text-slate-800">{r.parent_name}</p>
                            <p className="text-xs text-slate-400">{r.parent_email}</p>
                          </td>
                          <td className="px-8 py-4">
                            <p className="font-semibold text-slate-800">{r.professional_name}</p>
                            <p className="text-xs text-slate-400">{r.professional_email}</p>
                          </td>
                          <td className="px-8 py-4">
                            <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-bold ${
                              r.status === 'active'  ? 'bg-emerald-100 text-emerald-700' :
                              r.status === 'pending' ? 'bg-amber-100 text-amber-700'    :
                                                       'bg-red-100 text-red-600'
                            }`}>{r.status}</span>
                          </td>
                          <td className="px-8 py-4 text-slate-500 text-sm">
                            {new Date(r.invited_at).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' })}
                          </td>
                          <td className="px-8 py-4 text-right">
                            <button onClick={() => handleDeleteRelation(r.id)}
                              className="w-9 h-9 border border-red-100 bg-white rounded-lg text-red-500 flex items-center justify-center hover:bg-red-50 transition ml-auto"
                              title="Supprimer cette relation">
                              <i className="fa-regular fa-trash-can text-sm" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Section>
          )}

          {/* ══ VIEW : MESSAGES ══ */}
          {view === 'messages' && (
            <Section
              title="Tous les messages"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{adminMessages.length} message(s)</span>}
            >
              {/* Filters */}
              <div className="flex flex-wrap items-center gap-3 mb-5">
                <input
                  type="date"
                  value={msgDateFilter}
                  onChange={e => setMsgDateFilter(e.target.value)}
                  className="px-3 py-2 border border-slate-200 rounded-xl text-sm text-slate-700 bg-white focus:outline-none focus:border-brand-orange transition"
                  title="Filtrer par date"
                />
                <input
                  type="text"
                  value={msgNameFilter}
                  onChange={e => setMsgNameFilter(e.target.value)}
                  placeholder="Rechercher par nom…"
                  className="px-3 py-2 border border-slate-200 rounded-xl text-sm text-slate-700 bg-white focus:outline-none focus:border-brand-orange transition w-48"
                />
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Rôle :</span>
                  {(['all', 'parent', 'professional'] as const).map(r => (
                    <button key={r} type="button" onClick={() => setMsgRoleFilter(r)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all
                        ${msgRoleFilter === r ? 'bg-brand-orange text-white border-brand-orange' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
                      {r === 'all' ? 'Tous' : r === 'parent' ? '‍‍ Parent' : ' Professionnel'}
                    </button>
                  ))}
                </div>
                {(msgDateFilter || msgNameFilter || msgRoleFilter !== 'all') && (
                  <button onClick={() => { setMsgDateFilter(''); setMsgNameFilter(''); setMsgRoleFilter('all'); }}
                    className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-red-50 text-red-500 border border-red-200 hover:bg-red-100 transition">
                    <i className="fa-solid fa-xmark mr-1" /> Réinitialiser
                  </button>
                )}
              </div>

              {monitorLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : (() => {
                const filtered = adminMessages.filter(m => {
                  const dateOk = !msgDateFilter || m.created_at.startsWith(msgDateFilter);
                  const nameOk = !msgNameFilter || m.sender_name.toLowerCase().includes(msgNameFilter.toLowerCase()) || m.receiver_name.toLowerCase().includes(msgNameFilter.toLowerCase());
                  const roleOk = msgRoleFilter === 'all' || m.sender_role === msgRoleFilter || m.receiver_role === msgRoleFilter;
                  return dateOk && nameOk && roleOk;
                });
                return filtered.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                    <i className="fa-solid fa-comments text-5xl" />
                    <p className="font-medium">Aucun message correspondant.</p>
                  </div>
                ) : (
                  <div className="overflow-x-auto -mx-8 -mb-8">
                    <table className="w-full">
                      <thead>
                        <tr className="border-b border-slate-100">
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Expéditeur</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Destinataire</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Enfant</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Contenu</th>
                          <th className="text-left px-8 py-4 text-xs uppercase tracking-wider text-slate-500 font-bold">Date</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filtered.map(m => (
                          <tr key={m.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                            <td className="px-8 py-4">
                              <p className="font-semibold text-slate-800">{m.sender_name}</p>
                              <p className="text-xs text-slate-400 capitalize">{m.sender_role === 'professional' ? ' Professionnel' : '‍‍ Parent'}</p>
                            </td>
                            <td className="px-8 py-4">
                              <p className="font-semibold text-slate-800">{m.receiver_name}</p>
                              <p className="text-xs text-slate-400 capitalize">{m.receiver_role === 'professional' ? ' Professionnel' : '‍‍ Parent'}</p>
                            </td>
                            <td className="px-8 py-4 text-slate-600 text-sm">{m.child_name}</td>
                            <td className="px-8 py-4 text-slate-600 text-sm max-w-xs truncate">{m.content}</td>
                            <td className="px-8 py-4 text-slate-500 text-sm whitespace-nowrap">
                              {new Date(m.created_at).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' })}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                );
              })()}
            </Section>
          )}

          {/* ══ VIEW : NOTES CLINIQUES ══ */}
          {view === 'notes' && (
            <Section
              title="Toutes les notes cliniques"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{adminNotes.length} note(s)</span>}
            >
              {monitorLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <span className="w-10 h-10 rounded-full border-4 border-slate-200 border-t-brand-orange animate-spin" />
                  <p>Chargement…</p>
                </div>
              ) : adminNotes.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-3">
                  <i className="fa-solid fa-notes-medical text-5xl" />
                  <p className="font-medium">Aucune note clinique enregistrée.</p>
                </div>
              ) : (
                <div className="flex flex-col gap-4">
                  {adminNotes.map(n => (
                    <div key={n.id} className="bg-slate-50 border border-slate-100 border-l-4 border-l-brand-orange rounded-xl p-5">
                      <div className="flex items-center justify-between mb-2 flex-wrap gap-2">
                        <div className="flex items-center gap-2">
                          <i className="fa-solid fa-stethoscope text-brand-orange text-sm" />
                          <span className="font-bold text-slate-800 text-sm">Dr. {n.professional_name}</span>
                          <span className="text-xs text-slate-400">{n.professional_email}</span>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="inline-flex items-center gap-1.5 bg-orange-100 text-orange-700 px-3 py-1 rounded-full text-xs font-semibold">
                            <i className="fa-solid fa-baby text-[10px]" /> {n.child_name}
                          </span>
                          <span className="text-xs text-slate-400">
                            {new Date(n.date).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' })}
                          </span>
                        </div>
                      </div>
                      <p className="text-slate-600 text-sm leading-relaxed">{n.content}</p>
                    </div>
                  ))}
                </div>
              )}
            </Section>
          )}

          {/* ══ VIEW : DEMANDES ══ */}
          {view === 'registrations' && (            <Section
              title="Demandes d'inscription"
              badge={<span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-4 py-1.5 rounded-full text-sm font-semibold">{pending.length} en attente</span>}
            >
              {pending.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 gap-5">
                  <div className="w-20 h-20 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-4xl">
                    <i className="fa-solid fa-check" />
                  </div>
                  <div className="text-center">
                    <h3 className="text-xl font-bold text-slate-800 mb-1">Tout est à jour !</h3>
                    <p className="text-slate-500">Vous n'avez aucune demande d'inscription en attente.</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  {pending.map(reg => (
                    <div key={reg.id} className="flex items-center gap-5 p-5 bg-slate-50 rounded-xl border border-slate-100">
                      <div className="w-12 h-12 rounded-full bg-brand-orange flex items-center justify-center font-bold text-white text-lg shrink-0">
                        {reg.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-slate-900">{reg.name}</p>
                        <p className="text-sm text-slate-500">{reg.email}</p>
                        {reg.created_at && (
                          <p className="text-xs text-slate-400 mt-0.5">
                            {new Date(reg.created_at).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
                          </p>
                        )}
                      </div>
                      <span className="inline-flex items-center gap-2 bg-orange-100 text-orange-700 px-3 py-1.5 rounded-full text-xs font-semibold shrink-0">
                        <i className="fa-solid fa-house-user" /> Parent
                      </span>
                      <div className="flex gap-2 shrink-0">
                        <button onClick={() => handleApprove(reg.id)} disabled={actLoading}
                          className="flex items-center gap-1.5 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-semibold rounded-lg transition">
                          <i className="fa-solid fa-check" /> Accepter
                        </button>
                        <button onClick={() => handleReject(reg.id)} disabled={actLoading}
                          className="flex items-center gap-1.5 px-4 py-2 bg-white border border-red-200 text-red-500 hover:bg-red-50 text-sm font-semibold rounded-lg transition">
                          <i className="fa-solid fa-xmark" /> Refuser
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Section>
          )}

        </div>
      </div>

      {/* ── Modals ── */}
      <EditContentModal content={editingContent} isOpen={!!editingContent} onClose={() => setEditingContent(null)} onSave={handleEditSave} isLoading={loading} />
      <DeleteContentModal contentId={deletingContentId} contentTitle={deletingTitle} isOpen={!!deletingContentId} onClose={() => { setDeletingContentId(null); setDeletingTitle(''); }} onConfirm={handleDeleteConfirm} isLoading={loading} />

      {/* ── Toasts ── */}
      <ToastStack toasts={toasts} onRemove={removeToast} />

    </div>
  );
};

// ============================================================================
// CHILD DASHBOARD — Espace enfant AIDAA
// ============================================================================
import { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../features/auth/hooks/useAuth';
import { Video, Activity } from '../features/content/types/content.types';
import { MemoryGame } from '../features/games/MemoryGame';
import { ColorMatchGame } from '../features/games/ColorMatchGame';
import { EmotionGame } from '../features/games/EmotionGame';
import { SortingGame } from '../features/games/SortingGame';
import { CountingGame } from '../features/games/CountingGame';
import { PatternGame } from '../features/games/PatternGame';
import { PuzzleWordGame } from '../features/games/PuzzleWordGame';
import { SoundGame } from '../features/games/SoundGame';
import api from '../lib/api';
import LanguageSwitcher from '../components/ui/LanguageSwitcher';

const BACKEND_BASE = 'http://localhost:5000';

const buildMediaUrl = (url?: string): string | null => {
  if (!url) return null;
  return url.startsWith('http') ? url : `${BACKEND_BASE}${url.startsWith('/') ? '' : '/'}${url}`;
};

interface Stats   { total_points: number; total_activities: number }
interface Badge   { id: number; name: string; emoji: string; color: string }
interface Sequence {
  id: number; title: string; description: string; emoji: string;
  duration_minutes: number; difficulty: string; steps?: SeqStep[];
}
interface SeqStep {
  id: number; step_number: number; title: string; description: string;
  emoji: string; duration_seconds: number;
}
interface AACSymbol { id: number; label: string; emoji: string; category: string; color: string }

const CAT_CONFIG = {
  enfant: { label: 'Enfant', emoji: '', color: '#10b981' },
  jeune:  { label: 'Jeune',  emoji: '', color: '#3b82f6' },
  adulte: { label: 'Adulte', emoji: '', color: '#8b5cf6' },
};

// Video thumbnail gradient colors — cycle through them
const VIDEO_GRADIENTS = [
  'from-orange-300 to-red-400',
  'from-green-300 to-emerald-500',
  'from-blue-300 to-indigo-500',
  'from-purple-300 to-fuchsia-500',
  'from-yellow-300 to-amber-500',
  'from-teal-300 to-cyan-500',
];

// ============================================================================
// SEQUENCE VIEWER MODAL
// ============================================================================
function SequenceViewer({ sequence, onClose, onComplete }: {
  sequence: Sequence;
  onClose: () => void;
  onComplete: (score: number, dur: number) => void;
}): JSX.Element {
  const [step, setStep] = useState(0);
  const [done, setDone] = useState(false);
  const startRef = useRef(Date.now());
  const { t } = useTranslation();
  const steps = sequence.steps ?? [];
  const totalSteps = steps.length;
  const current = steps[step];
  const progressPct = totalSteps > 0 ? ((step) / totalSteps) * 100 : 0;

  const handleNext = () => {
    if (step < totalSteps - 1) { setStep(s => s + 1); }
    else { setDone(true); onComplete(totalSteps * 10, Math.round((Date.now() - startRef.current) / 1000)); }
  };

  return (
    <div className="fixed inset-0 z-[900] flex items-center justify-center p-5" style={{ background: 'rgba(15,35,24,0.88)', backdropFilter: 'blur(6px)' }}>
      <div className="bg-white rounded-3xl p-7 w-full max-w-lg shadow-2xl">
        {/* Header */}
        <div className="flex justify-between items-center mb-4">
          <div>
            <h2 className="text-xl font-extrabold text-slate-800">{sequence.emoji} {sequence.title}</h2>
            <p className="text-xs text-slate-500 mt-1">{totalSteps} étapes • {sequence.duration_minutes} min</p>
          </div>
          <button onClick={onClose} className="w-9 h-9 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-500 flex items-center justify-center text-base transition">✕</button>
        </div>
        {/* Progress */}
        <div className="h-2.5 bg-slate-100 rounded-full mb-6 overflow-hidden">
          <div className="h-full bg-gradient-to-r from-brand-green to-emerald-400 rounded-full transition-all duration-500" style={{ width: `${progressPct}%` }} />
        </div>
        {!done && current ? (
          <>
            <div className="text-center mb-5">
              <span className="inline-block bg-emerald-50 text-emerald-700 text-xs font-bold rounded-full px-4 py-1 mb-4">Étape {step + 1} / {totalSteps}</span>
              <div className="w-24 h-24 rounded-full bg-gradient-to-br from-emerald-100 to-emerald-200 flex items-center justify-center text-5xl mx-auto mb-4 shadow-lg">{current.emoji}</div>
              <h3 className="text-2xl font-extrabold text-slate-800 mb-2">{current.title}</h3>
              <p className="text-slate-500 leading-relaxed">{current.description}</p>
            </div>
            <div className="flex gap-3 mt-6">
              {step > 0 && (
                <button onClick={() => setStep(s => s - 1)} className="flex-1 py-3.5 rounded-xl border-2 border-slate-200 bg-white text-slate-700 font-bold hover:bg-slate-50 transition">← {t('childDash.prevStep')}</button>
              )}
              <button onClick={handleNext} className="flex-[2] py-3.5 rounded-xl bg-gradient-to-r from-brand-green to-emerald-400 text-white font-bold shadow-lg hover:opacity-90 transition">
                {step < totalSteps - 1 ? `${t('childDash.nextStep')} →` : `✅ ${t('childDash.finish')} !`}
              </button>
            </div>
          </>
        ) : done ? (
          <div className="text-center py-4">
            <div className="text-6xl mb-3"></div>
            <h3 className="text-2xl font-extrabold text-emerald-700 mb-2">Bravo ! Séquence terminée !</h3>
            <p className="text-emerald-600 mb-5">Tu as gagné {totalSteps * 10} points !</p>
            <button onClick={onClose} className="px-8 py-3.5 rounded-xl bg-gradient-to-r from-brand-green to-emerald-400 text-white font-bold hover:opacity-90 transition">Retour </button>
          </div>
        ) : (
          <p className="text-center text-slate-400">{t('childDash.noSequences')}</p>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// MAIN CHILD DASHBOARD
// ============================================================================
export const ChildDashboard = (): JSX.Element => {
  const { logout } = useAuth();
  const navigate   = useNavigate();
  const { t }      = useTranslation();

  const childId   = parseInt(localStorage.getItem('selected_child_id') ?? '0', 10);
  const childName = localStorage.getItem('selected_child_name') ?? 'Participant';
  const childCat  = (localStorage.getItem('selected_child_category') ?? 'enfant') as 'enfant' | 'jeune' | 'adulte';
  const catCfg    = CAT_CONFIG[childCat] ?? CAT_CONFIG.enfant;

  const [activeTab, setActiveTab]         = useState<'library' | 'sequences' | 'aac' | 'games'>('library');
  const [videos,     setVideos]           = useState<Video[]>([]);
  const [activities, setActivities]       = useState<Activity[]>([]);
  const [loadingLib, setLoadingLib]       = useState(true);
  const [sequences,  setSequences]        = useState<Sequence[]>([]);
  const [loadingSeq, setLoadingSeq]       = useState(false);
  const [activeSequence, setActiveSequence] = useState<Sequence | null>(null);
  const [aacSymbols,    setAACSymbols]    = useState<AACSymbol[]>([]);
  const [aacCategories, setAACCategories] = useState<string[]>([]);
  const [activeAACCat,  setActiveAACCat]  = useState<string>('Besoins');
  const [aacPhrase,     setAACPhrase]     = useState<AACSymbol[]>([]);
  const [loadingAAC,    setLoadingAAC]    = useState(false);
  const [activeGame, setActiveGame]       = useState<'memory' | 'color' | 'emotion' | 'sorting' | 'counting' | 'pattern' | 'puzzle_word' | 'sound' | null>(null);
  const [stats,  setStats]  = useState<Stats>({ total_points: 0, total_activities: 0 });
  const [badges, setBadges] = useState<Badge[]>([]);

  const fetchStats = useCallback(async () => {
    if (!childId) return;
    try {
      const [s, b] = await Promise.all([
        api.get(`/api/gamification/${childId}/stats`),
        api.get(`/api/gamification/${childId}/badges`),
      ]);
      if (s.data.success) setStats(s.data.data);
      if (b.data.success) setBadges(b.data.data);
    } catch { /* ignore */ }
  }, [childId]);

  useEffect(() => {
    const load = async () => {
      setLoadingLib(true);
      try {
        const [vRes, aRes] = await Promise.all([
          api.get(`/api/content?type=video&participant_category=${childCat}`),
          api.get(`/api/content?type=activity&participant_category=${childCat}`),
        ]);
        if (vRes.data.success) setVideos(vRes.data.data ?? []);
        if (aRes.data.success) setActivities(aRes.data.data ?? []);
      } catch (e) { console.error(e); }
      finally { setLoadingLib(false); }
    };
    load(); fetchStats();
  }, [childCat, fetchStats]);

  useEffect(() => {
    if (activeTab !== 'sequences' || sequences.length > 0) return;
    const load = async () => {
      setLoadingSeq(true);
      try {
        const res = await api.get(`/api/sequences?category=${childCat}`);
        if (res.data.success) setSequences(res.data.data ?? []);
      } catch (e) { console.error(e); }
      finally { setLoadingSeq(false); }
    };
    load();
  }, [activeTab, childCat, sequences.length]);

  useEffect(() => {
    if (activeTab !== 'aac' || aacSymbols.length > 0) return;
    const load = async () => {
      setLoadingAAC(true);
      try {
        const [symRes, catRes] = await Promise.all([
          api.get(`/api/aac/symbols?participant_category=${childCat}`),
          api.get('/api/aac/categories'),
        ]);
        if (symRes.data.success) setAACSymbols(symRes.data.data ?? []);
        if (catRes.data.success) {
          const cats: string[] = catRes.data.data ?? [];
          setAACCategories(cats);
          if (cats.length > 0) setActiveAACCat(cats[0]);
        }
      } catch (e) { console.error(e); }
      finally { setLoadingAAC(false); }
    };
    load();
  }, [activeTab, childCat, aacSymbols.length]);

  const logActivity = useCallback(async (contentId: number, action: string, score = 0, duration = 0) => {
    if (!childId) return;
    try {
      await api.post('/api/activity-log', { childId, contentId, status: score > 0 ? 'completed' : 'started', score, duration_seconds: duration, action });
      setStats(p => ({ total_points: p.total_points + score, total_activities: p.total_activities + 1 }));
    } catch (e) { console.error(e); }
  }, [childId]);

  const logGameScore = useCallback(async (gameId: number | string, score: number, duration: number) => {
    if (!childId) return;
    try {
      const res = await api.post(`/api/gamification/${childId}/score`, { gameId, score, duration_seconds: duration });
      if (res.data.newBadges?.length > 0) setBadges(p => [...p, ...res.data.newBadges]);
      setStats(p => ({ total_points: p.total_points + score, total_activities: p.total_activities + 1 }));
    } catch (e) { console.error(e); }
  }, [childId]);

  const openSequence = async (seq: Sequence) => {
    if (seq.steps) { setActiveSequence(seq); return; }
    try {
      const res = await api.get(`/api/sequences/${seq.id}`);
      if (res.data.success) setActiveSequence(res.data.data);
    } catch (e) { console.error(e); }
  };

  const speak = (text: string) => {
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const utt = new SpeechSynthesisUtterance(text);
    utt.lang = 'fr-FR'; utt.rate = 0.85;
    window.speechSynthesis.speak(utt);
  };

  // Active tab classes — exact match with child.html
  const tabCls = (tab: string) => tab === activeTab
    ? 'flex items-center gap-3 px-6 h-full bg-orange-100 text-brand-orange font-semibold border-b-2 border-brand-orange rounded-t-xl transition'
    : 'flex items-center gap-3 px-6 h-full text-slate-600 hover:text-slate-900 border-b-2 border-transparent hover:border-slate-300 rounded-t-xl transition';

  // Difficulty badge
  const diffCls = (d: string) => d === 'facile'
    ? 'bg-emerald-100 text-emerald-700 py-1.5 px-3 rounded-lg capitalize'
    : d === 'moyen'
    ? 'bg-amber-100 text-amber-700 py-1.5 px-3 rounded-lg capitalize'
    : 'bg-red-100 text-red-700 py-1.5 px-3 rounded-lg capitalize';

  return (
    <div className="bg-brand-bg text-brand-blue font-sans antialiased h-screen flex flex-col overflow-hidden">

      {/* ═══════════════════════════════ HEADER ═══════════════════════════════ */}
      <header className="bg-white/90 backdrop-blur-md border-b border-slate-200 h-20 flex items-center justify-between px-8 shadow-sm shrink-0 z-20 relative">
        {/* Left: avatar + greeting */}
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 rounded-full border-4 border-emerald-400 p-1 flex items-center justify-center bg-emerald-50 shadow-inner overflow-hidden text-3xl">
            {catCfg.emoji}
          </div>
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-slate-900">
              Bonjour <span className="text-brand-green">{childName}</span> ! 
            </h1>
            <p className="text-xs font-semibold uppercase tracking-widest text-slate-400 mt-1">
              Espace {catCfg.label} <i className="fa-solid fa-child-reaching" style={{ color: catCfg.color }}></i>
            </p>
          </div>
        </div>

        {/* Right: stats + buttons */}
        <div className="flex items-center gap-4">
          {/* Points */}
          <div className="bg-slate-50 border border-slate-100 rounded-2xl p-4 flex items-center gap-3 shadow-sm">
            <div className="w-10 h-10 rounded-full bg-yellow-100 text-yellow-600 flex items-center justify-center shadow-inner">
              <i className="fa-solid fa-star text-lg"></i>
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-800">{stats.total_points} <span className="text-sm text-slate-400">pts</span></p>
              <p className="text-[10px] font-semibold uppercase tracking-widest text-slate-400">Total</p>
            </div>
          </div>
          {/* Badges */}
          <div className="bg-slate-50 border border-slate-100 rounded-2xl p-4 flex items-center gap-3 shadow-sm">
            <div className="w-10 h-10 rounded-full bg-brand-green/10 text-brand-green flex items-center justify-center shadow-inner">
              <i className="fa-solid fa-medal text-lg"></i>
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-800">{badges.length} <span className="text-sm text-slate-400">badges</span></p>
              <p className="text-[10px] font-semibold uppercase tracking-widest text-slate-400">Gagnés</p>
            </div>
          </div>
          {/* Action buttons */}
          <div className="flex gap-2 ml-4 items-center">
            <LanguageSwitcher variant="light" />
            <button onClick={() => navigate('/child-selection')} className="bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:border-slate-300 rounded-xl px-5 py-2.5 flex items-center gap-2.5 shadow-sm transition">
              <i className="fa-solid fa-arrow-left text-xs"></i> Retour
            </button>
            <button onClick={logout} className="bg-red-50 hover:bg-red-500 text-red-600 hover:text-white rounded-xl px-5 py-2.5 flex items-center gap-2.5 shadow-sm transition">
              <i className="fa-solid fa-power-off text-sm"></i> {t('childDash.disconnect')}
            </button>
          </div>
        </div>
      </header>

      {/* ═══════════════════════════════ NAV TABS ═════════════════════════════ */}
      <nav className="bg-white border-b border-slate-200 h-16 flex items-center px-10 shrink-0 z-10 relative">
        <div className="flex gap-2 h-full pt-2">
          <button onClick={() => setActiveTab('library')} className={tabCls('library')}>
            <i className="fa-solid fa-book-open w-5 text-center"></i> {t('childDash.navVideos')}
          </button>
          <button onClick={() => setActiveTab('sequences')} className={tabCls('sequences')}>
            <i className="fa-solid fa-list-ol w-5 text-center"></i> {t('childDash.navSequences')}
          </button>
          <button onClick={() => setActiveTab('aac')} className={tabCls('aac')}>
            <i className="fa-regular fa-comment-dots w-5 text-center"></i> {t('childDash.navAAC')}
          </button>
          <button onClick={() => setActiveTab('games')} className={tabCls('games')}>
            <i className="fa-solid fa-gamepad w-5 text-center"></i> {t('childDash.navGames')}
          </button>
        </div>
      </nav>

      {/* ═══════════════════════════════ MAIN CONTENT ════════════════════════ */}
      <main className="flex-1 overflow-y-auto p-10 pb-20 relative">

        {/* ══════════════ MODULE A — BIBLIOTHÈQUE ══════════════════════════ */}
