                    <p className="text-sm text-slate-400 mt-2">Demande à ton accompagnateur d'ajouter du contenu.</p>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* ══════════════ MODULE B — SÉQUENCES ═════════════════════════════ */}
        {activeTab === 'sequences' && (
